    // Development-specific warning suppression
    if (process.env.NODE_ENV === 'development') {
      // Suppress noisy development warnings that don't affect functionality
      if (warning.code === 'css-unused-selector') return;
      if (warning.code === 'a11y-missing-attribute' && warning.message.includes('img')) return;
      if (warning.code === 'a11y-click-events-have-key-events') return;
    }

    // Optional: Debug warning suppression (uncomment for debugging)
    // if (warning.code === 'unknown-prop') {
    //   console.log('Suppressed warning:', warning.message);
    // }

    // Dynamic SvelteKit version detection and prop handling
    const svelteKitVersion = process.env.npm_package_dependencies_sveltekit ||
                            require('./package.json').devDependencies['@sveltejs/kit'];

    // Base SvelteKit internal props (common across versions)
    const baseSvelteKitProps = [
      'params', 'route', 'url', 'status', 'error', 'form', 'data',
      'beforeNavigate', 'afterNavigate', 'invalidateAll', 'preloadData',
      'updated', 'page', 'stores', 'snapshot', 'state'
    ];

    // Version-specific additional props
    const versionSpecificProps = svelteKitVersion?.startsWith('^2.') ?
      ['navigating', 'routeId', 'browser', 'dev', 'assets', 'version', 'base'] : [];
